import { useState } from "react";

// Rendered only once loaded: <ProfileForm key={p.id} profile={p} />
export function ProfileForm({ profile }: { profile: Profile }) {
  // Controlled: the counter needs the text on every keystroke
  const [bio, setBio] = useState(profile.bio);

  async function save(data: FormData) {
    await saveProfile({ name: String(data.get("name")), bio });
  }

  return (
    <form action={save}>
      {/* Uncontrolled: nothing reads it until submit */}
      <input name="name" defaultValue={profile.name} />
      <textarea value={bio} onChange={(e) => setBio(e.target.value)} />
      <p>{bio.length}/160</p>
      <button type="submit">Save</button>
    </form>
  );
}
